// HTML export: the 360 degree panorama viewer Pannellum 2.5.6 (MIT licence, Matthew Petroff, https://github.com/mpetroff/pannellum), unmodified,
// kept as base 64 text and written into an exported page only when the note holds a panorama. Licence text: licences/MIT-Pannellum.txt.
const PANNELLUM_JS = ``;
const PANNELLUM_CSS = ``;

// Script and style sheet of the viewer, decoded.
export function pannellumAssets(): { js: string; css: string } {
  const decode = (b64: string): string => {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return new TextDecoder().decode(bytes);
  };
  return { js: decode(PANNELLUM_JS), css: decode(PANNELLUM_CSS) };
}
